def fit_plus(centers, radius=13):
    res=[]
    for r0 in range(0,64):
        for c0 in range(0,64):
            ok=True
            for (r,c) in centers:
                on_row = (r==r0) and abs(c-c0)<=radius and c!=c0
                on_col = (c==c0) and abs(r-r0)<=radius and r!=r0
                if not (on_row or on_col): ok=False;break
            if ok: res.append((r0,c0))
    return res
